        "question": "पृथ्वी के अक्ष के उत्तरी िसरे को उत्तरी ध्रुव कहते हैं।\n\n2. 450 अक्षांश की लंबाई िवषुवत रेखा की आधी होती है।\n\n3. पृथ्वी के अक्ष की समांतरता है।\n\n4. अपसौर (Aphelion) अवस्था में पृथ्वी के पिरभ्रमण की गित\nतीव्र होती है।",
