        "correctAnswer": 3,
        "explanation": "उत्तरी ध्रुव पृथ्वी पर सबसे उत्तरी िबंदु है‚ अथार्त पृथ्वी के अक्ष के उत्तरी\nिसरे को ही उत्तरी ध्रुव (North Pole) कहा जाता है। अत: कथन\n(1) सही है।\n45° अक्षांश रेखा‚ िवषुवत रेखा एवं ध्रुवों के मध्य भाग से होकर गुजरती है।\nइसका Cosine 45° = 0.707; अत: इसकी लंबाई = 0.707× 40090.28\n= 28343.832 िकमी. है‚ जबिक िवषुवत रेखा की लंबाई लगभग 40090.28\nिकमी. है। अत: यह िवषुवत रेखा की आधी न होकर आधे से अिधक है। 60°\nअक्षांश रेखा िवषुवत रेखा की आधी होती है‚ िजसका Cosine 60°= 0.5 है।\nपृथ्वी के अक्ष की समांतरता से आशय है‚ जब पृथ्वी सूयर् की पिरक्रमा करती\nहै‚ तब पृथ्वी का अक्ष अपनी पूवर् िस्थित के सापेक्ष समांतर एवं समान कोण\n(23½°) पर झुका होता है। अत: कथन (3) सही है।\nअपसौर (Aphelion) की िस्थित 4 जुलाई की िनकटतम ितिथ को होती\nहै‚ जब पृथ्वी सूयर् से सवार्िधक दूरी पर होती है। अपसौर के समय पृथ्वी के\nपिरक्रमण की गित कम हो जाती है।\n\n*"
