        "correctAnswer": 0,
        "explanation": "टेलीग्रािफक पठार वस्तुत: एक हाइड्रोग्रािफक िमथक है। 19वीं शताब्दी के\nमध्य में अमेिरकी समुद्र िवज्ञानी मैथ्यू फोंटेन मौरी (Matthew Fontaine\nMaury) ने समुद्री गहराइयों का चाटर् तैयार करने के दौरान यह नोट िकया\nिक उत्तर अटलांिटक (एटलांिटक) महासागर में मध्य का भाग उथला है‚\nिजसे उसने समुद्रीय टेलीग्राफ केबल िबछाने के िलए उपयुक्त मानते हुए\n‘टेलीग्रािफक पठार’ का नाम िदया। उसके अनुसार‚ यह पठार अटलांिटक\nमहासागर में न्यूफाउंडलैंड से आयरलैंड तक िवस्तािरत था। वषर् 1925-27\nके दौरान जमर्नी के अनुसंधान पोत ‘मीिटओर’ (Meteor) द्वारा संग्रिहत\nआंकड़ों के आधार पर वैज्ञािनकों ने यह माना िक वास्तव में यह पठार एक\nसतत कटक है‚ जो िक अटलांिटक महासागर बेिसन में आगे तक िवस्तािरत\nहै। बाद के अध्ययनाें के आधार पर इसे मध्य-अटलांिटक कटक (Mid-\nAtlantic Ridge) का नाम िदया गया। मध्य-अटलांिटक कटक के उत्तरी\nभाग को डॉिल्फन कटक (Dolphin Ridge) के नाम से जाना जाता है‚ जो\nिक उत्तर में एक िवस्तृत पठार (पूवर् नाम– टेलीग्रािफक पठार) के रूप में है।\nइस प्रकार टेलीग्रािफक कटक को मध्य-अटलांिटक कटक के उत्तरी भाग\nअथार्त उत्तर अटलांिटक कटक का िहस्सा मानना ही उिचत है।\n\n*\nS घािटयां"
